double SamplerState::AdjustedLogit(TokenId token, float logit) const noexcept {
  const auto found = std::ranges::lower_bound(penalty_counts_, token, {},
                                              &TokenPenalty::token);
  const double bias = token < config_.logit_bias.size() ? config_.logit_bias[token] : 0.0;
  return bias + (found == penalty_counts_.end() || found->token != token
             ? static_cast<double>(logit)
             : Penalize(logit, config_, *found));
}

std::vector<float> SamplerState::ReportingLogits(std::span<const float> logits) const {
  auto row = config_.constraint ? ConstrainedLogits(logits) : std::vector<float>(logits.begin(), logits.end());
  const double temperature = config_.temperature > 0 ? config_.temperature : 1;
  for (std::size_t i=0;i<row.size();++i) if(std::isfinite(row[i])) row[i]=static_cast<float>(AdjustedLogit(i,row[i])/temperature);
  return row;
}
